import type { LucideIcon } from 'lucide-react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type AboutValue = {
  title: string
  description: string
  icon?: LucideIcon
}

export type AboutValuesSectionProps = {
  eyebrow?: string
  title: string
  description: string
  values: AboutValue[]
  statement?: string
  className?: string
}

export function AboutValuesSection({
  eyebrow = 'Sobre nós',
  title,
  description,
  values,
  statement,
  className,
}: AboutValuesSectionProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="grid gap-10 lg:grid-cols-[0.9fr_1.1fr] lg:gap-16">
          <header className="lg:sticky lg:top-24 lg:self-start">
            <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
              {eyebrow}
            </p>
            <h2 className="mt-4 text-balance text-3xl font-bold tracking-tight md:text-5xl">
              {title}
            </h2>
            <p className="mt-5 max-w-xl text-lg leading-8 text-muted-foreground">{description}</p>
            {statement ? (
              <p className="mt-8 border-l-2 border-primary pl-5 text-lg font-medium leading-8">
                {statement}
              </p>
            ) : null}
          </header>

          <div className="grid gap-4 sm:grid-cols-2">
            {values.map((value, index) => {
              const Icon = value.icon
              return (
                <article
                  key={value.title}
                  className={cn(
                    'group min-h-56 rounded-3xl border bg-card p-6 transition duration-300 hover:border-primary/30 hover:shadow-lg',
                    index === 0 && 'sm:col-span-2 sm:min-h-64',
                  )}
                >
                  <div className="flex items-start justify-between">
                    <span className="flex size-11 items-center justify-center rounded-2xl bg-primary/10 text-primary">
                      {Icon ? <Icon className="size-5" aria-hidden="true" /> : `0${index + 1}`}
                    </span>
                    <ArrowUpRight
                      className="size-5 text-muted-foreground transition group-hover:-translate-y-1 group-hover:translate-x-1 group-hover:text-primary motion-reduce:transform-none"
                      aria-hidden="true"
                    />
                  </div>
                  <h3 className="mt-10 text-xl font-semibold">{value.title}</h3>
                  <p className="mt-3 leading-7 text-muted-foreground">{value.description}</p>
                </article>
              )
            })}
          </div>
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import type { HTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

export type GalleryGridItem = {
  src: string
  alt: string
  title?: string
  description?: string
  href?: string
  width?: number
  height?: number
}

export interface GalleryGridProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
  items: readonly GalleryGridItem[]
  columns?: 2 | 3 | 4
  aspect?: 'square' | 'video' | 'portrait'
  variant?: 'grid' | 'masonry'
  emptyMessage?: string
}

export function GalleryGrid({
  items,
  columns = 3,
  aspect = 'square',
  variant = 'grid',
  emptyMessage = 'Nenhuma imagem disponível.',
  className,
  ...props
}: GalleryGridProps) {
  const columnsClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-2 lg:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]
  const aspectClass = { square: 'aspect-square', video: 'aspect-video', portrait: 'aspect-[3/4]' }[
    aspect
  ]

  if (!items.length) {
    return (
      <div
        className={cn(
          'rounded-2xl border border-dashed p-8 text-center text-muted-foreground',
          className,
        )}
      >
        {emptyMessage}
      </div>
    )
  }

  return (
    <section
      aria-label="Galeria de imagens"
      className={cn('grid grid-cols-1 gap-4', columnsClass, className)}
      {...props}
    >
      {items.map((item, index) => {
        const content = (
          <>
            <div
              className={cn(
                'relative overflow-hidden rounded-2xl bg-muted',
                variant === 'grid' && aspectClass,
              )}
            >
              <Image
                src={item.src}
                alt={item.alt}
                width={item.width ?? 900}
                height={item.height ?? 900}
                sizes={`(min-width: 1024px) ${Math.round(100 / columns)}vw, (min-width: 768px) 50vw, 100vw`}
                className={cn(
                  'h-full w-full object-cover transition duration-500 group-hover:scale-105',
                  variant === 'masonry' && 'h-auto',
                )}
              />
              {(item.title || item.description) && variant === 'grid' ? (
                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent p-5 pt-16 text-white">
                  {item.title ? <h3 className="font-semibold">{item.title}</h3> : null}
                  {item.description ? (
                    <p className="mt-1 text-sm text-white/80">{item.description}</p>
                  ) : null}
                </div>
              ) : null}
            </div>
            {(item.title || item.description) && variant === 'masonry' ? (
              <div className="px-1 pt-3">
                {item.title ? <h3 className="font-semibold">{item.title}</h3> : null}
                {item.description ? (
                  <p className="mt-1 text-sm text-muted-foreground">{item.description}</p>
                ) : null}
              </div>
            ) : null}
          </>
        )
        return item.href ? (
          <a
            key={`${item.src}-${index}`}
            href={item.href}
            className="group rounded-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          >
            {content}
          </a>
        ) : (
          <article key={`${item.src}-${index}`} className="group">
            {content}
          </article>
        )
      })}
    </section>
  )
}

import { cn } from '@/lib/utils'

export type StatsGridProps = {
  title?: string
  description?: string
  stats: Array<{ value: string; label: string; detail?: string }>
  columns?: 2 | 3 | 4
  className?: string
}

export function StatsGrid({ title, description, stats, columns = 4, className }: StatsGridProps) {
  const columnClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'stats-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="stats-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        {description ? <p className="mt-3 max-w-2xl text-muted-foreground">{description}</p> : null}
        <dl
          className={cn(
            'mt-10 grid gap-px overflow-hidden rounded-2xl border bg-border',
            columnClass,
          )}
        >
          {stats.map((stat) => (
            <div key={`${stat.value}-${stat.label}`} className="bg-background p-7">
              <dt className="text-sm text-muted-foreground">{stat.label}</dt>
              <dd className="mt-2 text-4xl font-bold tracking-tight text-primary">{stat.value}</dd>
              {stat.detail ? (
                <p className="mt-2 text-sm text-muted-foreground">{stat.detail}</p>
              ) : null}
            </div>
          ))}
        </dl>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'

import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type CTASplitPanelProps = {
  title: string
  description?: string
  eyebrow?: string
  actions?: ReactNode
  tone?: AccentTone
  className?: string
}

/** Painel com borda: texto à esquerda e ações à direita, empilhado no mobile. */
export function CTASplitPanel({
  title,
  description,
  eyebrow,
  actions,
  tone = 'industrial',
  className,
}: CTASplitPanelProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  return (
    <section className={cn('w-full py-12 lg:py-16', t.section, className)}>
      <div className="container">
        <div
          className={cn(
            'relative flex flex-col gap-8 overflow-hidden border p-8 sm:p-10 lg:flex-row lg:items-center lg:justify-between lg:p-12',
            t.panel,
            t.border,
            isGlow && 'rounded-2xl',
          )}
        >
          <span className={cn('absolute inset-y-0 left-0 w-1', t.line)} aria-hidden />
          <div className="max-w-2xl">
            {eyebrow ? (
              <span
                className={cn(
                  'mb-3 inline-block text-xs font-semibold uppercase tracking-[0.2em]',
                  t.accent,
                )}
              >
                {eyebrow}
              </span>
            ) : null}
            <h2 className={cn('text-2xl md:text-3xl', t.heading)}>{title}</h2>
            {description ? (
              <p className={cn('mt-4 text-base leading-relaxed', t.body)}>{description}</p>
            ) : null}
          </div>
          {actions ? <div className="flex shrink-0 flex-wrap gap-3">{actions}</div> : null}
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'

import { cn } from '@/lib/utils'

export type AccentTestimonial = {
  name: string
  content: string
  role?: string
  avatar?: string
  rating?: number
}

export function TestimonialAvatar({
  name,
  src,
  className,
}: {
  name: string
  src?: string
  className?: string
}) {
  const initials = name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('')

  return (
    <span
      className={cn(
        'relative flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden text-sm font-semibold',
        className,
      )}
    >
      {src ? (
        <Image src={src} alt={name} fill sizes="48px" className="object-cover" />
      ) : (
        <span aria-hidden>{initials}</span>
      )}
    </span>
  )
}

'use client'

import { useState } from 'react'
import { ChevronLeft, ChevronRight, Quote, Star } from 'lucide-react'
import type { Swiper as SwiperInstance } from 'swiper'
import { A11y, Autoplay, Keyboard } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import { TestimonialAvatar, type AccentTestimonial } from './TestimonialAvatar'

import 'swiper/css'

export type TestimonialsQuoteSliderProps = {
  title: string
  testimonials: readonly AccentTestimonial[]
  eyebrow?: string
  description?: string
  autoplayDelay?: number
  tone?: AccentTone
  className?: string
}

/** Slider de depoimentos com aspas, avaliação em estrelas, paginação e setas. */
export function TestimonialsQuoteSlider({
  title,
  testimonials,
  eyebrow,
  description,
  autoplayDelay = 5500,
  tone = 'industrial',
  className,
}: TestimonialsQuoteSliderProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const reduced = useReducedMotion()
  const [swiper, setSwiper] = useState<SwiperInstance | null>(null)
  const [activeIndex, setActiveIndex] = useState(0)
  const star = isGlow ? 'fill-[#ffb0eb] text-[#ffb0eb]' : 'fill-amber-500 text-amber-500'

  return (
    <section className={cn('relative overflow-hidden', t.section, className)}>
      <div className="container py-14 lg:py-16">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          layout="split"
          className="mb-10 lg:mb-12"
        />

        <Swiper
          modules={[A11y, Autoplay, Keyboard]}
          spaceBetween={0}
          slidesPerView={1}
          loop={testimonials.length > 3}
          keyboard={{ enabled: true }}
          autoplay={reduced ? false : { delay: autoplayDelay, disableOnInteraction: false }}
          breakpoints={{ 768: { slidesPerView: 2 }, 1024: { slidesPerView: 3 } }}
          onSwiper={setSwiper}
          onSlideChange={(instance) => setActiveIndex(instance.realIndex)}
          className={cn('border', t.border, isGlow && 'rounded-2xl')}
        >
          {testimonials.map((testimonial) => (
            <SwiperSlide key={testimonial.name + testimonial.content} className="!h-auto">
              <article
                className={cn(
                  'flex h-full min-h-[22rem] flex-col justify-between border-l p-7 sm:p-8',
                  t.panel,
                  t.border,
                )}
              >
                <div>
                  <div className="mb-6 flex items-start justify-between gap-4">
                    <Quote className={cn('h-8 w-8', t.accent)} strokeWidth={1.5} aria-hidden />
                    {testimonial.rating ? (
                      <div
                        className="flex items-center gap-0.5"
                        role="img"
                        aria-label={`${testimonial.rating} de 5 estrelas`}
                      >
                        {Array.from({ length: testimonial.rating }, (_, index) => (
                          <Star key={index} className={cn('h-3.5 w-3.5', star)} aria-hidden />
                        ))}
                      </div>
                    ) : null}
                  </div>
                  <blockquote className={cn('text-base leading-relaxed', t.body)}>
                    &ldquo;{testimonial.content}&rdquo;
                  </blockquote>
                </div>
                <div className={cn('mt-8 flex items-center gap-4 border-t pt-6', t.border)}>
                  <TestimonialAvatar
                    name={testimonial.name}
                    src={testimonial.avatar}
                    className={cn('border', t.border, t.accent, isGlow && 'rounded-full')}
                  />
                  <div>
                    <p
                      className={cn(
                        'text-sm font-semibold tracking-wide',
                        !isGlow && 'uppercase',
                        t.strong,
                      )}
                    >
                      {testimonial.name}
                    </p>
                    {testimonial.role ? (
                      <p className={cn('mt-0.5 text-xs uppercase tracking-[0.16em]', t.muted)}>
                        {testimonial.role}
                      </p>
                    ) : null}
                  </div>
                </div>
              </article>
            </SwiperSlide>
          ))}
        </Swiper>

        <div className="mt-8 flex items-center justify-between gap-4">
          <div className="flex items-center gap-1.5">
            {testimonials.map((testimonial, index) => (
              <button
                key={testimonial.name + index}
                type="button"
                onClick={() => swiper?.slideToLoop(index)}
                className={cn('py-2', t.focus)}
                aria-label={`Ir para o depoimento ${index + 1}`}
                aria-current={index === activeIndex ? 'true' : undefined}
              >
                <span
                  className={cn(
                    'block h-0.5 transition-all duration-300',
                    index === activeIndex
                      ? cn('w-10', t.line)
                      : cn(
                          'w-7',
                          isGlow
                            ? 'bg-[#493849]'
                            : tone === 'industrial'
                              ? 'bg-slate-300'
                              : 'bg-white/15',
                        ),
                  )}
                />
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => swiper?.slidePrev()}
              className={cn(
                'flex h-10 w-10 items-center justify-center transition-colors',
                t.iconButton,
                t.focus,
              )}
              aria-label="Depoimento anterior"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <button
              type="button"
              onClick={() => swiper?.slideNext()}
              className={cn(
                'flex h-10 w-10 items-center justify-center transition-colors',
                t.iconButton,
                t.focus,
              )}
              aria-label="Próximo depoimento"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
          </div>
        </div>
      </div>
    </section>
  )
}

'use client'

import { useState, type ReactNode } from 'react'
import { useForm } from 'react-hook-form'
import { yupResolver } from '@hookform/resolvers/yup'
import * as yup from 'yup'
import { CheckCircle2, MessageCircle, Send } from 'lucide-react'

import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { AccentButton } from '@/components/library/primitives/AccentButton'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

const contactSchema = yup.object({
  name: yup.string().required('Nome é obrigatório'),
  email: yup.string().email('E-mail inválido').required('E-mail é obrigatório'),
  phone: yup.string().required('Telefone é obrigatório'),
  subject: yup.string().required('Assunto é obrigatório'),
  message: yup.string().required('Mensagem é obrigatória'),
})

export type ContactChannelsFormData = yup.InferType<typeof contactSchema>

export type ContactChannel = {
  label: string
  value: string
  icon: ReactNode
  href?: string
  external?: boolean
}

export type ContactChannelsSectionProps = {
  title: string
  onSubmit: (data: ContactChannelsFormData) => Promise<void> | void
  channels?: readonly ContactChannel[]
  eyebrow?: string
  description?: string
  formTitle?: string
  channelsTitle?: string
  channelsDescription?: string
  whatsapp?: { href: string; label?: string }
  successTitle?: string
  successDescription?: string
  layout?: 'cards' | 'joined'
  tone?: AccentTone
  className?: string
}

const fields = [
  { name: 'name', label: 'Nome', placeholder: 'Seu nome completo', type: 'text' },
  { name: 'email', label: 'E-mail', placeholder: 'Seu e-mail', type: 'email' },
  { name: 'phone', label: 'Telefone', placeholder: 'Seu telefone', type: 'tel' },
  { name: 'subject', label: 'Assunto', placeholder: 'Assunto da mensagem', type: 'text' },
] as const

/** Seção de contato com formulário validado (react-hook-form + yup) e lista de canais. */
export function ContactChannelsSection({
  title,
  onSubmit,
  channels = [],
  eyebrow,
  description,
  formTitle,
  channelsTitle = 'Informações de contato',
  channelsDescription,
  whatsapp,
  successTitle = 'Mensagem enviada',
  successDescription = 'Obrigado pelo contato. Nossa equipe retornará em breve.',
  layout = 'cards',
  tone = 'glow',
  className,
}: ContactChannelsSectionProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const joined = layout === 'joined'
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [isSubmitted, setIsSubmitted] = useState(false)
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<ContactChannelsFormData>({ resolver: yupResolver(contactSchema) })

  const submit = async (data: ContactChannelsFormData): Promise<void> => {
    setSubmitError(null)
    try {
      await onSubmit(data)
      setIsSubmitted(true)
      reset()
    } catch {
      setSubmitError('Não foi possível enviar sua mensagem. Tente novamente.')
    }
  }

  const label = cn('mb-2 block text-[0.65rem] uppercase tracking-[0.2em]', t.muted)
  const field = cn('h-12', t.input)
  const darkPanel = joined && tone === 'industrial'
  const channelText = darkPanel
    ? {
        label: 'text-slate-400',
        value: 'text-white',
        icon: 'text-amber-500',
        border: 'border-white/10',
      }
    : { label: t.muted, value: t.strong, icon: t.accent, border: t.border }

  return (
    <section className={cn('w-full', t.section, className)}>
      <div className="container py-14 lg:py-16">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          layout="split"
          className="mb-10 lg:mb-12"
        />

        {isSubmitted ? (
          <div
            className={cn(
              'mx-auto max-w-2xl border px-8 py-14 text-center sm:px-12',
              t.panel,
              t.border,
              isGlow && 'rounded-xl',
            )}
            role="status"
          >
            <CheckCircle2 className={cn('mx-auto mb-6 h-10 w-10', t.accent)} aria-hidden />
            <h3 className={cn('text-3xl', t.heading, isGlow && 'mx-auto')}>{successTitle}</h3>
            <p className={cn('mt-4 text-base leading-relaxed', t.body)}>{successDescription}</p>
            <AccentButton
              tone={tone}
              onClick={() => setIsSubmitted(false)}
              icon={<Send className="h-4 w-4" />}
              className="mx-auto mt-8"
            >
              Enviar nova mensagem
            </AccentButton>
          </div>
        ) : (
          <div
            className={cn(
              'grid grid-cols-1 lg:grid-cols-12',
              joined ? cn('border', t.border) : 'gap-10 lg:gap-12',
            )}
          >
            <div
              className={cn(
                'p-6 sm:p-8 lg:col-span-7 lg:p-10',
                t.panel,
                !joined && cn('border', t.border, isGlow && 'rounded-xl'),
              )}
            >
              {formTitle ? <h3 className={cn('mb-6 text-2xl', t.heading)}>{formTitle}</h3> : null}
              <form onSubmit={handleSubmit(submit)} className="space-y-5" noValidate>
                <div className="grid gap-5 sm:grid-cols-2">
                  {fields.map((item) => {
                    const error = errors[item.name]?.message
                    const id = `contact-${item.name}`
                    return (
                      <div key={item.name}>
                        <label htmlFor={id} className={label}>
                          {item.label}
                        </label>
                        <Input
                          id={id}
                          type={item.type}
                          placeholder={item.placeholder}
                          aria-invalid={Boolean(error)}
                          aria-describedby={error ? `${id}-error` : undefined}
                          className={field}
                          {...register(item.name)}
                        />
                        {error ? (
                          <p id={`${id}-error`} className={cn('mt-1.5 text-sm', t.error)}>
                            {error}
                          </p>
                        ) : null}
                      </div>
                    )
                  })}
                </div>
                <div>
                  <label htmlFor="contact-message" className={label}>
                    Mensagem
                  </label>
                  <Textarea
                    id="contact-message"
                    rows={6}
                    placeholder="Descreva sua necessidade"
                    aria-invalid={Boolean(errors.message)}
                    aria-describedby={errors.message ? 'contact-message-error' : undefined}
                    className={cn(t.input, 'min-h-[160px] resize-y py-3')}
                    {...register('message')}
                  />
                  {errors.message?.message ? (
                    <p id="contact-message-error" className={cn('mt-1.5 text-sm', t.error)}>
                      {errors.message.message}
                    </p>
                  ) : null}
                </div>
                {submitError ? (
                  <p className={cn('text-sm', t.error)} role="alert">
                    {submitError}
                  </p>
                ) : null}
                <div className="flex justify-center pt-1">
                  <AccentButton
                    tone={tone}
                    type="submit"
                    disabled={isSubmitting}
                    icon={<Send className="h-4 w-4" />}
                  >
                    {isSubmitting ? 'Enviando...' : 'Enviar mensagem'}
                  </AccentButton>
                </div>
              </form>
            </div>

            <div
              className={cn(
                'lg:col-span-5',
                joined &&
                  cn(
                    'border-t p-7 sm:p-8 lg:border-l lg:border-t-0 lg:p-10',
                    t.border,
                    darkPanel ? 'bg-slate-950 text-white' : t.alt,
                  ),
              )}
            >
              <h3
                className={cn(
